The following is a reported fault in an open-source AI software project.

Issue title: vmap of jit does not work in presence of hi types

Issue report:
```
### Description

The following modified `test_tuple_vmap` from `hijax_test.py` fails. The modification is just adding `jax.jit` on the function to be mapped.

```
  def test_tuple_vmap(self):
    tup = make_tup(jnp.arange(3.), jnp.arange(3.))
    out = jax.vmap(jax.jit(lambda x: x), in_axes=TupSpec((0, 0)),
                   out_axes=TupSpec((0, 0)), axis_size=3)(tup)
    self.assertAllClose(out.elts, tup.elts)
```

the error is the following:
```
jax/_src/pjit.py:254: in cache_miss
    executable, pgle_profiler, const_args) = _run_python_pjit(
jax/_src/pjit.py:142: in _run_python_pjit
    out_flat = jit_p.bind(*args_flat, **p.params)
               ^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^
jax/_src/core.py:664: in bind
    return self.bind_with_trace(prev_trace, args, avals, params)
           ^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^
jax/_src/core.py:672: in bind_with_trace
    return trace.process_primitive(self, args, params)
           ^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^
jax/_src/interpreters/batching.py:263: in process_primitive
    val_out, dim_out = fancy_primitive_batchers[p](
jax/_src/pjit.py:1451: in _pjit_batcher
    in_shardings = tuple(
_ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _

.0 = <list_iterator object at 0x114c73c70>

    in_shardings = tuple(
        _pjit_batcher_for_sharding(i, axis_in, axis_data.spmd_name, ctx_mesh,
>                                  aval.ndim)
                                   ^^^^^^^^^
        if axis_in is not None else i
        for axis_in, i, aval in zip(dims_in, in_shardings, new_jaxpr.in_avals))
E   AttributeError: 'TupTy' object has no attribute 'ndim'
```

A simple workaround is possible where we defer reading `.ndim` if the sharding is unspecified. But a real fix should consider other shardings, and it seems that `_pjit_batcher` has not been updated for hijax.


### System info (python version, jaxlib version, accelerator, etc.)

```
jax:    0.10.2.dev20260602+bd317d60c4
jaxlib: 0.10.1
numpy:  2.4.6
python: 3.12.11 (main, Aug 28 2025, 17:00:08) [Clang 20.1.4 ]
device info: cpu-1, 1 local devices"
process_count: 1
platform: uname_result(system='Darwin', node='necula-mac.roam.internal', release='24.6.0', version='Darwin Kernel Version 24.6.0: Tue Apr 21 20:19:12 PDT 2026; root:xnu-11417.140.69.710.16~1/RELEASE_ARM64_T6041', machine='arm64')
```
```

Reproduction attempt:
1. Created a Python 3.12 virtual environment and installed the runtime dependencies from `requirements.txt`.
2. Pointed `PYTHONPATH` at the local `codebase/` checkout and executed `repro.py`.
3. Observed the `AttributeError: 'TupTy' object has no attribute 'ndim'` traceback from the `jit` batching path.

Observed evidence: Running `bash run_repro.sh` in a Python 3.12 venv with the local JAX checkout reproduces the bug. The repro prints `typeof(tup) = Tup{float32[3],float32[3]}` and then fails with `AttributeError: 'TupTy' object has no attribute 'ndim'` from `jax/_src/pjit.py` while evaluating `jax.vmap(jax.jit(lambda x: x), in_axes=TupSpec((0, 0)), out_axes=TupSpec((0, 0)), axis_size=3)(tup)`.

Minimal reproduction script:
```python
from __future__ import annotations

from dataclasses import dataclass
import itertools as it

import jax
import jax.numpy as jnp
from jax import typeof
from jax._src.hijax import HiType, MappingSpec, register_hitype


@dataclass
class HiTup:
  elts: tuple

  def __repr__(self):
    return "Tup{" + ",".join(map(repr, self.elts)) + "}"


@dataclass(frozen=True)
class TupTy(HiType):
  tys: tuple

  def __repr__(self):
    return "Tup{" + ",".join(repr(a) for a in self.tys) + "}"

  def __hash__(self):
    return hash(self.tys)

  def __eq__(self, other):
    return isinstance(other, TupTy) and self.tys == other.tys

  def lo_ty(self):
    return list(self.tys)

  def lower_val(self, hi_val: HiTup):
    return [lo for ty, elt in zip(self.tys, hi_val.elts)
            for lo in ty.lower_val(elt)]

  def raise_val(self, *elts_flat):
    elts_iter = iter(elts_flat)
    return HiTup(tuple(
        ty.raise_val(*it.islice(elts_iter, len(ty.lo_ty())))
        for ty in self.tys
    ))

  def to_tangent_aval(self):
    return TupTy(tuple(ty.to_tangent_aval() for ty in self.tys))

  def normalize(self):
    return TupTy(tuple(ty.normalize() for ty in self.tys))

  def dec_rank(self, size, spec):
    return TupTy(tuple(ty.dec_rank(size, s) for ty, s in zip(self.tys, spec.val)))

  def inc_rank(self, size, spec):
    return TupTy(tuple(ty.inc_rank(size, 0) for ty in self.tys))

  def leading_axis_spec(self):
    return TupSpec(tuple(ty.leading_axis_spec() for ty in self.tys))

  def shard(self, mesh, manual_axes, check_vma, spec):
    return TupTy(tuple(
        ty.shard(mesh, manual_axes, check_vma, s)
        for ty, s in zip(self.tys, spec.val)
    ))

  def unshard(self, mesh, check_vma, spec):
    return TupTy(tuple(
        ty.unshard(mesh, check_vma, s) for ty, s in zip(self.tys, spec.val)
    ))

  def vspace_add(self, x_tup, y_tup):
    return x_tup


register_hitype(HiTup, lambda t: TupTy(tuple(map(typeof, t.elts))))


@dataclass(frozen=True)
class TupSpec(MappingSpec):
  val: tuple


def make_tup(*elts):
  return HiTup(tuple(elts))


def main():
  tup = make_tup(jnp.arange(3.), jnp.arange(3.))
  print("typeof(tup) =", typeof(tup))
  print("calling jax.vmap(jax.jit(lambda x: x)) on a hijax tuple")
  out = jax.vmap(
      jax.jit(lambda x: x),
      in_axes=TupSpec((0, 0)),
      out_axes=TupSpec((0, 0)),
      axis_size=3,
  )(tup)
  print("out =", out)


if __name__ == "__main__":
  main()
```

