A repository contains the following reported issue:

Issue #38857: Dangerous channel using in Kubelet.podKiller

Issue description:
https://github.com/kubernetes/kubernetes/blob/1d3c7ca7581272124b0853a606bb88387a4db9ea/pkg/kubelet/kubelet_pods.go#L756

There is a defer calling in this method:

    defer close(resultCh)

It may crash the goroutine created at line 777, which then will make the whole kubelet crash.

A simple fix
```go
	func (kl *Kubelet) podKiller() {
		killing := sets.NewString()
		resultCh := make(chan types.UID)

		defer close(resultCh)

		for {
			select {
			case podPair, ok := <-kl.podKillingCh:
				if !ok {
					return
				}

				runningPod := podPair.RunningPod
				apiPod := podPair.APIPod

				if killing.Has(string(runningPod.ID)) {
					// The pod is already being killed.
					break
				}
				killing.Insert(string(runningPod.ID))
				go func(apiPod *v1.Pod, runningPod *kubecontainer.Pod, ch chan types.UID) {
					defer func() {
						recover() // avoid this goroutine crashing
					}
					defer func() {
						ch <- runningPod.ID
					}()
					glog.V(2).Infof("Killing unwanted pod %q", runningPod.Name)
					err := kl.killPod(apiPod, runningPod, nil, nil)
					if err != nil {
						glog.Errorf("Failed killing the pod %q: %v", runningPod.Name, err)
					}
				}(apiPod, runningPod, resultCh)

			case podID := <-resultCh:
				killing.Delete(string(podID))
			}
		}
	}
```

Another simple fix
```go
	func (kl *Kubelet) podKiller() {
		killing := sets.NewString()
		resultCh := make(chan types.UID)

		// defer close(resultCh)
		closedCh := make(chan struct{}) // this channel is used to avoid goroutine 777 hanging
		defer close(closedCh)

		for {
			select {
			case podPair, ok := <-kl.podKillingCh:
				if !ok {
					return
				}

				runningPod := podPair.RunningPod
				apiPod := podPair.APIPod

				if killing.Has(string(runningPod.ID)) {
					// The pod is already being killed.
					break
				}
				killing.Insert(string(runningPod.ID))
				go func(apiPod *v1.Pod, runningPod *kubecontainer.Pod, ch chan types.UID) {
					defer func() {
						select {
						case ch <- runningPod.ID:
						case <- closedCh: // avoid this goroutine hanging
						}
					}()
					glog.V(2).Infof("Killing unwanted pod %q", runningPod.Name)
					err := kl.killPod(apiPod, runningPod, nil, nil)
					if err != nil {
						glog.Errorf("Failed killing the pod %q: %v", runningPod.Name, err)
					}
				}(apiPod, runningPod, resultCh)

			case podID := <-resultCh:
				killing.Delete(string(podID))
			}
		}
	}
```

